["..BYYYYYYB..",".BBYYYYYYBB.","BBBBYYYYBBBB","BB.BWWWWB.BB","BB.BYYYYB.BB",".BBYYYYYYBB.","..BBBBBBBB..","....B..B...."]].map(r=>makeSprite(r,PAL));
const GOEI=[
[".R........R.",".RR......RR.","..RRR..RRR..","..RRRRRRRR..",".RRRWWWWRRR.",".RRRWWWWRRR.","..RRRRRRRR..","...RR..RR..."],
["..RRRRRRRR..",".RRRRRRRRRR.","RRRWWWWWWRRR","RRRWWWWWWRRR",".RRRRRRRRRR.","..RR....RR..","..R......R..","............"]].map(r=>makeSprite(r,PAL));
const BOSS=[
["GG..........GG","GGG........GGG",".GGGGGGGGGGGG.","..GGGGGGGGGG..","..GGGBBBBBGG..","..GGBBBBBBGG..","..GGBBBBBBGG..",".GGGBBBBBBGGG.",".GG..BBBB..GG.",".G...BBBB...G."],
["..GGGBBBBBGG..",".GGGGBBBBBGGG.","GGGGBBBBBBGGGG","GG.GGBBBBGG.GG","..GGGBBBBGGG..","..GGBBBBBBGG..","..GGBBBBBBGG..",".GG..BBBB..GG.",".G...BBBB...G.",".....G..G....."]];
const bossPal={W:'#fff',B:'#40a0d0',R:'#e8402a',Y:'#ffd800',G:'#28c828',P:'#9040e0'};
