const FLAGS=[[1,makeFlag('#ffffff')],[5,makeFlag('#40a0ff')],[10,makeFlag('#30e030')],
             [20,makeFlag('#ffd800')],[30,makeFlag('#ff7020')],[50,makeFlag('#c050ff')]];

/* ---------------- Web Audio (synthesized) ---------------- */
let AC=null, master=null, noiseBuf=null, muted=false;
function initAudio(){
  if(AC)return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=0.22; master.connect(AC.destination);
    noiseBuf=AC.createBuffer(1,AC.sampleRate,AC.sampleRate);
    const d=noiseBuf.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  }catch(e){}
}
function tone(f0,f1,dur,type,vol,delay=0){
  if(!AC||muted)return;
  const t=AC.currentTime+delay;
  const o=AC.createOscillator(), g=AC.createGain();
  o.type=type;
  o.frequency.setValueAtTime(Math.max(1,f0),t);
  o.frequency.exponentialRampToValueAtTime(Math.max(1,f1),t+dur);
  g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t+dur+0.03);
}
function noiseSnd(dur,vol,f0,f1,delay=0){
  if(!AC||muted||!noiseBuf)return;
  const t=AC.currentTime+delay;
  const s=AC.createBufferSource(); s.buffer=noiseBuf; s.loop=true;
  const fl=AC.createBiquadFilter(); fl.type='lowpass';
  fl.frequency.setValueAtTime(f0,t);
  fl.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  const g=AC.createGain();
  g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(fl); fl.connect(g); g.connect(master);
  s.start(t); s.stop(t+dur+0.03);
}
const sndShot    =()=>tone(900,180,0.08,'square',0.12);
const sndEnemyDie=()=>{noiseSnd(0.28,0.35,1400,80);tone(320,50,0.25,'triangle',0.18);};
