const sndCapture =()=>{tone(700,90,0.7,'square',0.2);noiseSnd(0.6,0.15,600,100);};
const sndDock    =()=>{tone(300,1300,0.28,'sine',0.22);tone(600,1600,0.28,'triangle',0.12,0.05);};
