/* starfield: scrolling, multicoloured, twinkling */
G.stars=[];
function initStars(){
  const cols=['#ffffff','#ffd800','#40a0ff','#ff5050','#c0c0c0'];
  for(let i=0;i<80;i++)G.stars.push({
    x:Math.random()*W,y:Math.random()*H,
    v:8+Math.random()*26,
    c:cols[(Math.random()*cols.length)|0],
    ph:Math.random()*6.28,sp:2+Math.random()*4});
}
function drawStars(){
  for(const s of G.stars){
    const tw=0.45+0.55*Math.abs(Math.sin(G.t*s.sp+s.ph));
    ctx.globalAlpha=tw;
    ctx.fillStyle=s.c;
    ctx.fillRect(s.x|0,s.y|0,1,1);
  }
  ctx.globalAlpha=1;
}
function enemySprite(e){
  const f=(Math.floor(G.t*6)%2);
  if(e.type==='zako')return ZAKO[f];
  if(e.type==='goei')return GOEI[f];
  if(e.type==='fighter')return sprFighterRed;
  const base=e.hit?2:0;
  return BOSSSPR[base+f];
}
function drawEnemies(){
  for(const e of G.enemies){
    if(e.captured){ // captive fighter held above its boss
      drawSpriteRot(sprFighterRed,e.x,e.y-18,Math.PI);
    }
    if(e.state==='HOVER'&&e.beamT>0.35&&e.beamT<4.2)drawBeam(e);
    const sp=enemySprite(e);
    drawSpriteRot(sp,e.x,e.y,e.a-Math.PI/2);
  }
}
function drawSpriteRot(img,x,y,a){
  ctx.save();
  ctx.translate(Math.round(x),Math.round(y));
  if(a)ctx.rotate(a);
  ctx.drawImage(img,-(img.width>>1),-(img.height>>1));
  ctx.restore();
}
function drawBeam(b){
  const topY=b.y+8;
  const t=G.t;
  for(let i=2;i>=0;i--){
    const hw=(40+i*8)*(0.9+0.1*Math.sin(t*10+i));
    ctx.fillStyle=['rgba(60,120,255,0.35)','rgba(80,180,255,0.30)','rgba(180,240,255,0.25)'][i];
    ctx.beginPath();
    ctx.moveTo(b.x,topY);
    ctx.lineTo(b.x-hw,H);
    ctx.lineTo(b.x+hw,H);
    ctx.closePath();ctx.fill();
  }
  // animated rungs
  ctx.strokeStyle='rgba(200,240,255,0.5)';
  ctx.lineWidth=1;
  const off=(t*60)%14;
  for(let y=topY+off;y<H;y+=14){
    const hw=52*(y-topY)/(H-topY);
    ctx.beginPath();ctx.moveTo(b.x-hw,y);ctx.lineTo(b.x+hw,y);ctx.stroke();
  }
}
function drawFreed(){
  if(G.freed)drawSpriteRot(sprFighter,G.freed.x,G.freed.y,0);
}
function drawPlayer(){
  const p=G.player;
  if(p.state==='alive'||p.state==='pull'){
    if(p.invuln>0&&Math.floor(G.t*12)%2)return; // blink while invulnerable
    if(p.dual){
      drawSpriteRot(sprFighter,p.x-7,p.y,0);
      drawSpriteRot(sprFighter,p.x+7,p.y,0);
    }else drawSpriteRot(sprFighter,p.x,p.y,0);
  }
}
function drawBullets(){
  ctx.fillStyle='#ffffff';
  for(const b of G.pbul)ctx.fillRect(b.x-0,b.y-3,1,6);
  for(const b of G.ebul){
    ctx.fillStyle='#c0a0ff';
    ctx.fillRect((b.x|0)-1,(b.y|0)-2,3,5);
    ctx.fillStyle='#ffffff';
    ctx.fillRect((b.x|0),(b.y|0)-1,1,2);
  }
}
function drawHUD(){
  drawText('1UP',4,4,'#ff4040');
  drawText(String(G.score).padStart(6,'0'),4,14,'#ffffff');
  drawText('HIGH SCORE',78,4,'#ff4040');
  drawText(String(G.hi).padStart(6,'0'),84,14,'#ffffff');
  // reserve ships bottom-left
  for(let i=0;i<Math.max(0,G.ships);i++)
    ctx.drawImage(sprIcon,6+i*10,H-14);
  // stage flags bottom-right
  let n=G.stage,x=W-10;
  const denoms=FLAGS.map(f=>f[0]);
  for(let i=denoms.length-1;i>=0;i--){
    while(n>=denoms[i]){
      n-=denoms[i];
      ctx.drawImage(FLAGS[i][1],x,H-18);
      x-=9;
      if(x<120)x=W-10; // wrap to a second row if many flags
    }
  }
}
function drawMessages(){
